-- ============================================================
-- ORION-HARDENING FASE 1 · P0-2b: revogar anon de RPCs SENSÍVEIS (não pegas pela regra financeira) · 2026-07-18
-- Contexto: além das 93 financeiras, 69 funções SECURITY DEFINER sensíveis
-- (admin_*, ajustes financeiros, moderação, e-mails de usuário, dispatch de campanha,
-- profit events) eram EXECUTÁVEIS por anon. Destaques SEM guarda: admin_apply_financial_adjustment
-- (move dinheiro), admin_get_auth_emails (vaza e-mail/PII), track_admin_profit_event (injeta receita),
-- approve/reject_advertiser_media (bypass de moderação). cyber_block_entity tem cyber_guard(); demais admin_get_*
-- com admin_assert_access. Ainda assim: anon não deve alcançá-las.
-- Decisão: revoke anon em todas; revoke authenticated nas 65 não chamadas por front/Edge
-- (comprovado por grep .rpc); mantém authenticated nas 4 chamadas pelo front; service_role sempre.
-- Reversível. Idempotente. SQL Editor (broifhfqmnzqoongtokm).
-- ============================================================

-- ETAPA A · 4 sensíveis chamadas pelo front: revoga anon/PUBLIC, mantém authenticated
DO $$ BEGIN EXECUTE 'REVOKE EXECUTE ON FUNCTION public.admin_get_auth_emails(uuid[]) FROM PUBLIC, anon'; EXECUTE 'GRANT EXECUTE ON FUNCTION public.admin_get_auth_emails(uuid[]) TO authenticated, service_role'; EXCEPTION WHEN undefined_function OR undefined_object THEN RAISE WARNING 'ausente: admin_get_auth_emails(uuid[])'; END $$;
DO $$ BEGIN EXECUTE 'REVOKE EXECUTE ON FUNCTION public.admin_get_dashboard_snapshot_rpc(timestamp with time zone,timestamp with time zone) FROM PUBLIC, anon'; EXECUTE 'GRANT EXECUTE ON FUNCTION public.admin_get_dashboard_snapshot_rpc(timestamp with time zone,timestamp with time zone) TO authenticated, service_role'; EXCEPTION WHEN undefined_function OR undefined_object THEN RAISE WARNING 'ausente: admin_get_dashboard_snapshot_rpc(timestamp with time zone,timestamp with time zone)'; END $$;
