-- VERIFICAÇÃO (esperado sensiveis_anon=0)
SELECT count(*) AS sensiveis_anon FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
WHERE n.nspname='public' AND p.prosecdef AND p.prorettype<>'trigger'::regtype
  AND has_function_privilege('anon', p.oid,'EXECUTE')
  AND (p.proname ~* '^admin_|_admin$|^delete_|^drop_|^approve_|^reject_|^moderat|financial|profit|balance|finance|auth_email|merchant_balance|motoboy_finance|payout|dispatch_admin|campaign_dispatch|_block_entity|bi_financial');

-- Adendo · 2 aprovações guardadas (backup/aoc) — defesa em profundidade, revoga anon
DO $$ BEGIN EXECUTE 'REVOKE EXECUTE ON FUNCTION public.backup_approve_recovery(bigint,boolean,text) FROM PUBLIC, anon'; EXCEPTION WHEN undefined_function OR undefined_object THEN NULL; END $$;
DO $$ BEGIN EXECUTE 'REVOKE EXECUTE ON FUNCTION public.aoc_approve_decision(bigint,boolean,text) FROM PUBLIC, anon'; EXCEPTION WHEN undefined_function OR undefined_object THEN NULL; END $$;
